  'O painel confere o usuário só na DNS escolhida. Se ela cair ou você migrar o usuário de servidor, ele procura nas outras DNS e o app passa a usar a nova automaticamente.' => array('pt' => 'O painel confere o usuário só na DNS escolhida. Se ela cair ou você migrar o usuário de servidor, ele procura nas outras DNS e o app passa a usar a nova automaticamente.', 'en' => 'The panel checks the user only on the chosen DNS. If it goes down or you move the user to another server, it searches the other DNS and the app switches automatically.', 'es' => 'El panel verifica el usuario solo en el DNS elegido. Si cae o mueves el usuario a otro servidor, busca en los otros DNS y la app cambia automáticamente.'),
  'servidor(es) DNS ativo(s) para a troca automática.' => array('pt' => 'servidor(es) DNS ativo(s) para a troca automática.', 'en' => 'active DNS server(s) for automatic switching.', 'es' => 'servidor(es) DNS activo(s) para el cambio automático.'),
  'DNS não encontrada. Escolha outra.' => array('pt' => 'DNS não encontrada. Escolha outra.', 'en' => 'DNS not found. Choose another one.', 'es' => 'DNS no encontrado. Elige otro.'),
  'A DNS "{}" recusou este usuário e senha. Confira os dados ou escolha outra DNS.' => array('pt' => 'A DNS "{0}" recusou este usuário e senha. Confira os dados ou escolha outra DNS.', 'en' => 'The DNS "{0}" rejected this username and password. Check the details or choose another DNS.', 'es' => 'El DNS "{0}" rechazó este usuario y contraseña. Revisa los datos o elige otro DNS.'),
  'A DNS "{}" não respondeu agora. Escolha outra DNS ou "Automático".' => array('pt' => 'A DNS "{0}" não respondeu agora. Escolha outra DNS ou "Automático".', 'en' => 'The DNS "{0}" did not respond now. Choose another DNS or "Automatic".', 'es' => 'El DNS "{0}" no respondió ahora. Elige otro DNS o "Automático".'),
