  'Disponível agora' => array('pt' => 'Disponível agora', 'en' => 'Available now', 'es' => 'Disponible ahora'),
  'Disponível em' => array('pt' => 'Disponível em', 'en' => 'Available on', 'es' => 'Disponible en'),
